import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type QuestionMarkClusterProps = Record<string, any>;

const QuestionMarkCluster: React.FC<QuestionMarkClusterProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  questionMarkColor = "#ffffff",
  count = 40,
  staggerFrames = 1.5,
  spread = 45,
  baseFontSize = 80,
  durationInSeconds = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Deterministic positions using a phyllotaxis spiral (sunflower pattern)
  // This ensures "no randomness" but a natural, clustered "expanding outward" look.
  const marks = useMemo(() => {
    const items = [];
    const goldenAngle = Math.PI * (3 - Math.sqrt(5)); // ~2.3999 rad

    for (let i = 0; i < count; i++) {
      const r = spread * Math.sqrt(i);
      const theta = i * goldenAngle;
      
      const x = r * Math.cos(theta);
      const y = r * Math.sin(theta);

      // Depth logic: newer (higher index) are slightly larger
      // Older (lower index) are naturally in the center
      const progress = i / count;
      
      // Newer ones (higher i) are larger
      const sizeMultiplier = 0.5 + (0.5 * progress); 
      
      // Newer ones are brighter (full opacity), older ones dimmer
      const baseOpacity = 0.4 + (0.6 * progress);

      items.push({
        id: i,
        x,
        y,
        sizeMultiplier,
        baseOpacity,
        rotation: (theta * 180) / Math.PI - 90, // Orient somewhat towards center or spiral
      });
    }
    return items;
  }, [count, spread]);

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {marks.map((mark, index) => {
          // Stagger logic
          const delay = index * staggerFrames;
          
          // Only render if we've reached the start frame to save resources
          if (frame < delay) return null;

          // Spring animation for pop-in
          const spr = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 12,
              stiffness: 150,
              mass: 0.8,
            },
          });

          // Entrance opacity
          const entranceOpacity = interpolate(
            frame - delay,
            [0, 5],
            [0, 1],
            { extrapolateRight: "clamp" }
          );

          // Combined scale: base size * spring
          const currentScale = mark.sizeMultiplier * spr;
          
          // Combined opacity: base hierarchy opacity * entrance fade
          const currentOpacity = mark.baseOpacity * entranceOpacity;

          return (
            <div
              key={mark.id}
              style={{
                position: "absolute",
                left: width / 2 + mark.x,
                top: height / 2 + mark.y,
                transform: `translate(-50%, -50%) scale(${currentScale}) rotate(${mark.rotation * 0.1}deg)`, // minimal rotation for style
                opacity: currentOpacity,
                color: questionMarkColor,
                fontSize: baseFontSize,
                fontWeight: 900,
                lineHeight: 1,
                userSelect: "none",
                willChange: "transform, opacity",
                zIndex: index, // Newer on top as requested
                transition: "none",
              }}
            >
              ?
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default QuestionMarkCluster;